// Find the node in the model that is closest to the given (x, y) coordinates.
// This implementation iterates over all nodes stored in the RouteModel's
// internal vector (m_nodes) and selects the one with the smallest Euclidean
// distance.  Footway roads are already excluded from the node‑to‑road map,
// so we simply consider every node.
float best_dist = std::numeric_limits<float>::max();
Node* best_node = nullptr;

for (auto& node : m_nodes) {
    float dx = static_cast<float>(node.x) - x;
    float dy = static_cast<float>(node.y) - y;
    float dist = dx * dx + dy * dy;   // squared distance is sufficient for comparison
    if (dist < best_dist) {
        best_dist = dist;
        best_node = &node;
    }
}

// The model is guaranteed to contain at least one node, but guard against an
// empty graph to keep the function safe.
if (!best_node) {
    static Node dummy;
    return dummy;
}
return *best_node;
```

